import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
import {profileFigure} from './energy-graphs.js?v=20261023-physicscomplete01';
import {transferCases,temperatureAccount} from './energy-models.js?v=20261023-physicscomplete01';
export function showEnergy(kind='transfer',t=transferCases[0],reveal=true,profile={reactants:40,products:25,peak:90}){
 if(kind.startsWith('profile')){const data=kind==='profile-endo'?{reactants:40,products:55,peak:90}:profile;renderDiagram('From reactants to products','Relative energy · no numerical energy units',profileFigure(data)+'<p class="diagram-caption">A compares the chosen starting level with the peak. B compares the endpoint levels. Not a time graph.</p>','REACTION PROFILE · SYMBOLIC LEVELS');return;}
 if(kind==='endo')t=transferCases[1];const a=temperatureAccount(t.initial,t.final),out=a.direction==='out',text=(x,y,s,size=14)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f8f6f2" font-family="sans-serif" font-size="${size}">${s}</text>`;
 renderDiagram(reveal?(out?'Energy moves out':'Energy moves in'):'Predict the transfer',t.name,`<svg class="lab-svg" viewBox="0 0 440 300" role="img" aria-label="Reacting particles inside a system boundary, with measured surroundings outside. Initial ${t.initial} degrees Celsius; final ${t.final} degrees Celsius. ${reveal?(out?'Energy transfers from reaction to surroundings.':'Energy transfers from surroundings to reaction.'):'Predict reaction type and energy direction.'}"><defs><radialGradient id="energySphere" cx=".3" cy=".25"><stop stop-color="#f8f6f2"/><stop offset=".35" stop-color="#ed8b78"/><stop offset="1" stop-color="#9b584c"/></radialGradient></defs><rect x="22" y="45" width="396" height="205" rx="22" fill="#b7c8d611" stroke="#b7c8d6"/>${text(220,28,'Measured surroundings',17)}<rect x="55" y="85" width="155" height="130" rx="18" fill="#182e44" stroke="#ed8b78" stroke-dasharray="5 4"/>${[[92,128],[135,125],[175,145],[112,174],[153,178]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="13" fill="url(#energySphere)"/>`).join('')}${text(132,237,'Reacting particles',13)}${text(317,102,`${t.initial}°C → ${t.final}°C`,21)}${reveal?`<path d="M${out?225:387} 159H${out?387:225}" stroke="#ed8b78" stroke-width="4"/><path d="M${out?377:235} 150L${out?387:225} 159L${out?377:235} 168" fill="none" stroke="#ed8b78" stroke-width="4"/>${text(305,197,'Energy',15)}`:text(305,165,'Energy direction?',15)}${text(220,280,'Total energy is conserved',15)}</svg><p class="diagram-caption">Illustrative temperature readings and symbolic particles. Heat exchange with the wider room and apparatus is omitted.</p>`,'ENERGY TRANSFER MODEL · NOT TO SCALE');
}
